import type { Category, Finding, Severity } from "@/lib/audit/types";
import marketingEn from "@/lib/rules/packs/marketing-en.json";

/** One wording rule from a rule pack (generated by scripts/build-rulepack.py from MIT-licensed rule sets). */
export type PackRule = {
  code: string; category: Category; severity: Severity; pattern: string; ignoreCase: boolean;
  message: string; why: string; fix: string | null; source: string;
};

export const MARKETING_EN: PackRule[] = marketingEn.rules as PackRule[];

const compiled = new Map<string, RegExp>();
function regexFor(r: PackRule): RegExp {
  const key = `${r.code}\u0000${r.pattern}`;
  let re = compiled.get(key);
  if (!re) {
    // the unicode flag is only needed for \p{…} classes; without it case-insensitive matching is several times faster
    const flags = `g${r.ignoreCase ? "i" : ""}${r.pattern.includes("\\p{") ? "u" : ""}`;
    re = new RegExp(r.pattern, flags);
    compiled.set(key, re);
  }
  re.lastIndex = 0;
  return re;
}

/**
 * Wording heuristics (hype, unsupported absolute claims, vague sources, AI-typical phrasing).
 * Always medium confidence: a phrase match is a signal for the reviewer, not proof (proposal §7.4, §10.4).
 * `disabled` holds rule codes an organisation has switched off.
 */
export function checkRulePack(text: string, rules: PackRule[] = MARKETING_EN, disabled: ReadonlySet<string> = new Set()): Finding[] {
  const out: Finding[] = [];
  for (const r of rules) {
    if (disabled.has(r.code)) continue;
    for (const m of text.matchAll(regexFor(r))) {
      if (!m[0]) continue;
      out.push({
        quote: m[0], start: m.index!, end: m.index! + m[0].length,
        category: r.category, severity: r.severity, confidence: "medium", source: "rule", ruleCode: r.code,
        explanation: r.fix ? `${r.why} ${r.fix}` : `${r.why} ${r.message}`,
        suggestion: null, status: "open", label: null,
      });
    }
  }
  return out.sort((a, b) => a.start - b.start);
}
